import{_ as t}from"./chunks/22.DPtKHQKO.js";import{_ as o,a as r}from"./chunks/33.cCfpsNSZ.js";import{_ as a}from"./chunks/17.CpKVWXAe.js";import{_ as i,o as s,c as l,a0 as n}from"./chunks/framework.DRjqbEpm.js";const g=JSON.parse('{"title":"👑 Pro Features Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/pro-features.md","filePath":"en/guide/pro-features.md"}'),d={name:"en/guide/pro-features.md"};function u(c,e,h,p,m,b){return s(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="👑-pro-features-guide" tabindex="-1">👑 Pro Features Guide <a class="header-anchor" href="#👑-pro-features-guide" aria-label="Permalink to &quot;👑 Pro Features Guide&quot;">​</a></h1><p>V-Train has a <strong>Pro Version</strong>. You only pay one time. There are no monthly fees. Pay once, and use it forever! This page explains all the extra features you get with the Pro version.</p><hr><h2 id="🆓-free-version-vs-pro-version" tabindex="-1">🆓 Free Version vs Pro Version <a class="header-anchor" href="#🆓-free-version-vs-pro-version" aria-label="Permalink to &quot;🆓 Free Version vs Pro Version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Free Version</th><th>Pro Version</th></tr></thead><tbody><tr><td>Track Progress</td><td>✅ Unlimited Sites</td><td>✅ Unlimited Sites</td></tr><tr><td>Adaptive Engine</td><td>✅ Full Feature</td><td>✅ Full Feature</td></tr><tr><td>Share Rules</td><td>✅ Full Feature</td><td>✅ Full Feature</td></tr><tr><td>Backup &amp; Restore</td><td>✅ Full Feature</td><td>✅ Full Feature</td></tr><tr><td>Video Record Limit</td><td>⚠️ <strong>200 videos</strong></td><td>✅ <strong>Unlimited</strong></td></tr><tr><td>Floating Panel</td><td>✅</td><td>✅</td></tr><tr><td>Bookmark Vault</td><td>✅ Max 100 videos</td><td>✅ <strong>Unlimited</strong></td></tr><tr><td>Custom Covers</td><td>✅</td><td>✅</td></tr><tr><td>Passcode Lock</td><td>❌</td><td>✅</td></tr></tbody></table><hr><h2 id="📊-the-200-video-limit-free-version" tabindex="-1">📊 The 200 Video Limit (Free Version) <a class="header-anchor" href="#📊-the-200-video-limit-free-version" aria-label="Permalink to &quot;📊 The 200 Video Limit (Free Version)&quot;">​</a></h2><p>The Free version of V-Train can remember your progress for <strong>200 videos</strong>.</p><h3 id="how-v-train-cleans-up-old-data" tabindex="-1">How V-Train Cleans Up Old Data <a class="header-anchor" href="#how-v-train-cleans-up-old-data" aria-label="Permalink to &quot;How V-Train Cleans Up Old Data&quot;">​</a></h3><p>What happens when you watch your <strong>201st</strong> video?</p><ul><li>The system finds the oldest video record you have not watched in a long time.</li><li>It deletes that old record to make space.</li><li>It always keeps your newest 200 videos.</li></ul><blockquote><p>😅 Imagine a small robot that can only remember 200 things. When it learns something new, it must forget something old.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">💡 Bookmark Protection</p><p>If you save a video to your Bookmark Vault, V-Train will <strong>never delete</strong> its record. This is because a bookmark means the video is important to you!</p></div><div class="info custom-block"><p class="custom-block-title">Will this limit bother me?</p><ul><li>If you watch a few videos a week, you will not notice the limit.</li><li>If you watch many videos every day, your oldest records will disappear.</li><li>If you want to keep your progress forever, you should upgrade to Pro!</li></ul></div><hr><h2 id="🎯-pro-version-features" tabindex="-1">🎯 Pro Version Features <a class="header-anchor" href="#🎯-pro-version-features" aria-label="Permalink to &quot;🎯 Pro Version Features&quot;">​</a></h2><h3 id="_1-unlimited-video-records" tabindex="-1">1. Unlimited Video Records <a class="header-anchor" href="#_1-unlimited-video-records" aria-label="Permalink to &quot;1. Unlimited Video Records&quot;">​</a></h3><p>When you upgrade to Pro, the 200 video limit is removed. The system stops deleting your old records. You can save the progress of thousands of videos. V-Train will remember them all.</p><h3 id="_2-floating-panel-hover-panel" tabindex="-1">2. Floating Panel (Hover Panel) <a class="header-anchor" href="#_2-floating-panel-hover-panel" aria-label="Permalink to &quot;2. Floating Panel (Hover Panel)&quot;">​</a></h3><p>When you watch a video, a small panel appears on the screen:</p><blockquote><p><img src="'+t+'" alt="Floating Interaction Panel"></p></blockquote><p><strong>What the buttons do:</strong></p><table tabindex="0"><thead><tr><th>Button</th><th>Function</th></tr></thead><tbody><tr><td>👍 Like</td><td>Add a thumbs-up icon to the video picture.</td></tr><tr><td>👎 Dislike</td><td>Add a thumbs-down icon to the video picture.</td></tr><tr><td>❤️ Bookmark</td><td>Save the video to a folder.</td></tr><tr><td>📸 Screenshot</td><td>Take a picture of the video to use as a cover.</td></tr><tr><td>📚 Vault</td><td>Open your Bookmark Vault.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Move the panel!</p><p>You can click and drag the panel. V-Train will remember where you put it.</p></div><div class="info custom-block"><p class="custom-block-title">Turn off the panel</p><p>You can turn off this panel in the Dashboard.</p></div><h3 id="_3-bookmark-vault" tabindex="-1">3. Bookmark Vault <a class="header-anchor" href="#_3-bookmark-vault" aria-label="Permalink to &quot;3. Bookmark Vault&quot;">​</a></h3><p>A full-screen page to organize your favorite videos. Read more on the <a href="./bookmark-vault.html">Bookmark Vault Guide</a>.</p><h3 id="_4-custom-screenshot-covers" tabindex="-1">4. Custom Screenshot Covers <a class="header-anchor" href="#_4-custom-screenshot-covers" aria-label="Permalink to &quot;4. Custom Screenshot Covers&quot;">​</a></h3><p>Sometimes, website pictures disappear. You can click the 📸 button to take your own picture of the video.</p><ol><li>V-Train takes a picture of the video player.</li><li>The picture is made smaller to save space.</li><li>The picture is saved on your computer.</li><li>Your Bookmark Vault will now use this new picture as the cover.</li></ol><div class="warning custom-block"><p class="custom-block-title">❌ When does a screenshot fail?</p><ul><li>The website blocks screenshots for security.</li><li>The video is hidden inside another webpage.</li><li>You will see a red ❌ if it fails.</li></ul><p>Even if the screenshot fails, you can still save the video to your Bookmark Vault.</p></div><h3 id="_5-privacy-passcode-lock" tabindex="-1">5. Privacy Passcode Lock <a class="header-anchor" href="#_5-privacy-passcode-lock" aria-label="Permalink to &quot;5. Privacy Passcode Lock&quot;">​</a></h3><p>The Pro version lets you add a password to V-Train:</p><ul><li>You must type the password to open the Dashboard.</li><li>This stops other people from seeing what videos you watch.</li></ul><blockquote><p><img src="'+o+'" alt="Passcode Screen"></p></blockquote><hr><h2 id="🔑-how-to-buy-and-enable-pro" tabindex="-1">🔑 How to Buy and Enable Pro <a class="header-anchor" href="#🔑-how-to-buy-and-enable-pro" aria-label="Permalink to &quot;🔑 How to Buy and Enable Pro&quot;">​</a></h2><ol><li>Go to the <a href="https://v-train.lemonsqueezy.com/checkout/buy/3dbcb93a-052c-433c-9adb-5fdcf221cc17" target="_blank" rel="noreferrer">V-Train Pro Store</a>. (Pay once, no monthly fees).</li><li>After you pay, you will receive a <strong>License Key</strong>.</li><li>Open the V-Train <strong>Dashboard</strong>. Find the &quot;<strong>⚡ Unlock V-Train Pro</strong>&quot; button at the bottom.</li><li>Paste your License Key in the box.</li><li>V-Train will check the key online.</li><li>Success! All Pro features will unlock immediately.</li></ol><blockquote><p><img src="'+r+'" alt="Pro Upgrade Button"></p></blockquote><div class="tip custom-block"><p class="custom-block-title">💡 Keep your License Key safe!</p><p>You can use your License Key again if you buy a new computer. Save it in a safe place!</p></div><hr><h2 id="🆘-i-forgot-my-passcode" tabindex="-1">🆘 I Forgot My Passcode! <a class="header-anchor" href="#🆘-i-forgot-my-passcode" aria-label="Permalink to &quot;🆘 I Forgot My Passcode!&quot;">​</a></h2><p>If you forget your password, you can reset it:</p><blockquote><p><img src="'+a+'" alt="Forgot Passcode Button"></p></blockquote><ol><li>Click &quot;<strong>Forgot Passcode?</strong>&quot; on the password screen.</li><li>Enter your <strong>Pro License Key</strong>.</li><li>Your password will be removed.</li><li>You should create a new password and backup your data.</li></ol><div class="danger custom-block"><p class="custom-block-title">💀 I forgot my passcode AND lost my License Key</p><p>If you lose your License Key, you cannot reset your password. This is to protect your privacy. You must reinstall V-Train (this deletes all your data) and buy Pro again. <strong>Please keep your License Key safe!</strong></p></div><hr><h2 id="📞-support-and-links" tabindex="-1">📞 Support and Links <a class="header-anchor" href="#📞-support-and-links" aria-label="Permalink to &quot;📞 Support and Links&quot;">​</a></h2><ul><li>🛒 <strong>Buy Pro</strong>: <a href="https://v-train.lemonsqueezy.com/checkout/buy/3dbcb93a-052c-433c-9adb-5fdcf221cc17" target="_blank" rel="noreferrer">V-Train Pro Store</a></li><li>💬 <strong>Ask for Help</strong>: <a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>⭐ <strong>Chrome Web Store</strong>: <a href="https://chromewebstore.google.com/detail/v-train-adaptive-video-ba/cikabjkegiefjgalfncfoehmkpmkoiaf" target="_blank" rel="noreferrer">Chrome Web Store</a></li></ul><div class="info custom-block"><p class="custom-block-title">Pro License Rules</p><ul><li><strong>Pay once</strong>. No monthly fees.</li><li><strong>Valid forever</strong>. You get all future updates for free.</li><li>You can use the key again if you reset your browser.</li></ul></div>',50)])])}const P=i(d,[["render",u]]);export{g as __pageData,P as default};
